def digest(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def main() -> None:
    source_blocks = translation.blocks(SOURCE.read_text(encoding="utf-8"))
    target_blocks = translation.blocks(TARGET.read_text(encoding="utf-8"))
    records = [json.loads(line) for line in MANIFEST.read_text(encoding="utf-8").splitlines()]
    if not (len(source_blocks) == len(target_blocks) == len(records)):
        raise ValueError(f"alignment mismatch: {len(source_blocks)}, {len(target_blocks)}, {len(records)}")
    invalid = sorted(set(CORRECTIONS) - set(range(1, len(target_blocks) + 1)))
    if invalid:
        raise ValueError(f"invalid block indices: {invalid}")
    for index, value in CORRECTIONS.items():
        target_blocks[index - 1] = value
        record = records[index - 1]
        record.update(
            kind="author_reviewed_translation",
            target_chars=len(value),
            target_sha256=digest(value),
            target_numbers=dict(translation.normalized_numbers(value)),
            target_footnotes=translation.PROTECTED_RE.findall(value),
        )
        record["number_match"] = (
            translation.normalized_numbers(source_blocks[index - 1])
            == translation.normalized_numbers(value)
        )
        record["footnote_match"] = (
            translation.PROTECTED_RE.findall(source_blocks[index - 1])
            == record["target_footnotes"]
        )
    TARGET.write_text("\n\n".join(target_blocks) + "\n", encoding="utf-8")
    MANIFEST.write_text(
        "".join(json.dumps(record, ensure_ascii=False) + "\n" for record in records),
        encoding="utf-8",
    )
    sys.stdout.reconfigure(encoding="utf-8")
    print(f"[OK] applied {len(CORRECTIONS)} author-reviewed translations")


if __name__ == "__main__":
    main()
